export type CharToRhymeMap = Record<string, string[]>;

function buildCharToGroupMap(groups: RhymeGroupEntry[]): CharToRhymeMap {
  const map: CharToRhymeMap = {};
  groups.forEach(group => {
    group.chars.split(' ').filter(Boolean).forEach(char => {
      const ids = map[char] ?? (map[char] = []);
      if (!ids.includes(group.id)) ids.push(group.id);
    });
  });
  return map;
}

export const CHAR_TO_GROUPS: Record<RhymeBook, CharToRhymeMap> = {
  ping_shui: buildCharToGroupMap(PING_SHUI_GROUPS),
  ci_lin: buildCharToGroupMap(CI_LIN_GROUPS),
  xin_yun: buildCharToGroupMap(XIN_YUN_GROUPS),
};

