function buildCharToToneMap(tones: Record<'P' | 'Z', string>): Record<string, Array<'P' | 'Z'>> {
  const map: Record<string, Array<'P' | 'Z'>> = {};
  (['P', 'Z'] as const).forEach(tone => {
    tones[tone].split(' ').filter(Boolean).forEach(char => {
      const values = map[char] ?? (map[char] = []);
      if (!values.includes(tone)) values.push(tone);
    });
  });
  return map;
}

